#include "gesummv.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A, B, x and scalars alpha, beta exactly as in the
 * original PolyBench C version.
 *
 * C layout:
 *   A[i][j], B[i][j] with i as row, j as column.
 *
 * Halide layout:
 *   Buffer<num_t,2> A(j, i)
 *   Buffer<num_t,2> B(j, i)
 *   Buffer<num_t,1> x(i)
 *
 * i is the slow (row) dimension, j is the fast (column) dimension.
 */
static
void init_array(int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B,
                Halide::Buffer<num_t, 1> x) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    Func init_A("init_A"), init_B("init_B"), init_x("init_x");

    // x[i] = (i % n) / n;
    init_x(i) = cast<num_t>(i % n) / cast<int>(n);

    // A[i][j] = ((i * j + 1) % n) / n;
    // Stored as A(j, i) in the Buffer.
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // B[i][j] = ((i * j + 2) % n) / n;
    // Stored as B(j, i) in the Buffer.
    init_B(j, i) = cast<num_t>((i * j + 2) % n) / cast<int>(n);

    // ------------------------------------------------------------------
    // Scheduling for initialization
    //
    // We initialize A and B in row-major order with j (columns) as the
    // innermost dimension. This matches the buffer layout (j, i), so
    // vectorizing over j gives contiguous accesses and excellent locality.
    // x is a simple 1D vector; we just vectorize over i.
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec = natural_vector_size(type_of<num_t>(), target);

    // x is 1D; vectorize over i.
    init_x.compute_root()
          .vectorize(i, vec);

    // A and B are 2D; parallelize over rows (i), vectorize over columns (j).
    init_A.compute_root()
          .parallel(i)
          .vectorize(j, vec);

    init_B.compute_root()
          .parallel(i)
          .vectorize(j, vec);

    // Realize into the provided buffers.
    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //  - A, B are N x N matrices, stored as (j, i) = (column, row)
    //  - x, y are N-length vectors.
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // ------------------------------------------------------------------
    // Halide pipeline for GESUMMV:
    //
    // Original mathematical formulation (per row i):
    //   tmp[i]   = sum_j A[i][j] * x[j]
    //   y_acc[i] = sum_j B[i][j] * x[j]
    //   y[i]     = alpha * tmp[i] + beta * y_acc[i]
    //
    // Matrices A and B are stored as A(j, i), B(j, i) (column-major in j),
    // so j should be the fast-varying (inner) dimension to get contiguous
    // accesses.
    //
    // We implement the two matrix-vector products as a single Tuple-valued
    // reduction:
    //
    //   sums(i) = { tmp[i], y_acc[i] }
    //   sums(i) = { 0, 0 }
    //   sums(i) += { A(i,j)*x[j], B(i,j)*x[j] }
    //
    // This keeps exactly the same per-row accumulation order as the
    // original algorithm (bitwise identical for floating point), while
    // loading x(j) only once and improving cache locality.
    // ------------------------------------------------------------------
    Var i("i");
    RDom j(0, A.dim(0).extent(), "j");  // j runs over columns (0..n-1)

    // Tuple-valued Func accumulating both dot products in one pass.
    Func sums("sums");
    sums(i) = Tuple(cast<num_t>(0), cast<num_t>(0));  // {tmp, y_acc}
    sums(i) += Tuple(A_param(j, i) * x_param(j),
                     B_param(j, i) * x_param(j));

    // Final combination: y[i] = alpha * tmp[i] + beta * y_acc[i]
    Func y_func("y_func");
    Expr tmp_i   = sums(i)[0];
    Expr y_acc_i = sums(i)[1];
    y_func(i) = Expr(alpha) * tmp_i + Expr(beta) * y_acc_i;

    // ------------------------------------------------------------------
    // Scheduling
    //
    // Data layout:
    //   - A, B: Buffer(j, i) so j is contiguous in memory.
    //   - x:    Buffer(j)
    //   - y:    Buffer(i)
    //
    // We want:
    //   - Outer parallelism across rows i (independent dot products).
    //   - Inner vectorization across j for contiguous loads from A, B, x.
    //   - Good locality by computing sums(i, :) inside the loop over i.
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec = natural_vector_size(type_of<num_t>(), target);

    // Compute y at the top level, parallel across rows (i).
    y_func.compute_root()
          .parallel(i);

    // Compute sums per row i inside y_func's loop over i, so each row's
    // partial sums stay in L1/cache.
    sums.compute_at(y_func, i);

    // Vectorize the reduction over j. We split the reduction variable j
    // into [j_outer, j_inner] and vectorize j_inner. Since A, B, x are
    // all contiguous in j, this generates dense vector loads/stores.
    RVar j_outer("j_outer"), j_inner("j_inner");
    sums.update()
        .split(j, j_outer, j_inner, vec)
        .vectorize(j_inner);

    // Compile the kernel to machine code (JIT).
    y_func.compile_jit();

    // Measure execution time (kernel only).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination and allow checking).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print timing in seconds on stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
