    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // B[i][j] = ((i * j + 2) % n) / n;
    // Stored as B(j, i) in the Buffer.
    init_B(j, i) = cast<num_t>((i * j + 2) % n) / cast<int>(n);

    // Simple but cache- and vector-friendly schedules for initialization.
    // These run only once, but they are cheap to schedule and keep the
    // memory access pattern dense in the fast (j) dimension.

    Target init_target = get_host_target();
    const int vec_width = init_target.natural_vector_size<num_t>();

    // x is 1D and contiguous: vectorize across i.
    init_x
        .compute_root()
        .vectorize(i, vec_width);

    // A and B are 2D with j as the fast dimension: parallelize rows (i)
    // and vectorize across columns (j).
    init_A
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    init_B
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

