    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // Halide vars and reduction domain.
    Var i("i");
    // j runs over columns (dimension 0 of A and B).
    RDom j(0, A.dim(0).extent(), "j");

    // We compute the two dot-products A[i][:]·x and B[i][:]·x for each i.
    // To improve data locality and reduce memory traffic, we accumulate
    // both sums in a single pass over j using a Tuple-valued Func:
