    // and B in column-major order once per (i, j) instead of twice.

    Func acc("acc"), y_func("y_func");

    // Initialize tuple {tmp, y_acc} = {0, 0} per i.
    acc(i) = Tuple(cast<num_t>(0), cast<num_t>(0));

    // Update step: accumulate both sums in lockstep over j.
    Expr tmp_prev   = acc(i)[0];
    Expr yacc_prev  = acc(i)[1];
    Expr a_ij       = A_param(j, i) * x_param(j);
    Expr b_ij       = B_param(j, i) * x_param(j);
    acc(i) = Tuple(tmp_prev + a_ij,
                   yacc_prev + b_ij);

    // Final combination (scalar coefficients converted to Expr once).
    Expr alpha_e(alpha);
    Expr beta_e(beta);
    y_func(i) = alpha_e * acc(i)[0] + beta_e * acc(i)[1];

    // -------------------
    // Scheduling
    // -------------------

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size<num_t>();

    // Compute the final result in a single root loop over i, and
    // parallelize across rows. Each row's dot-products are independent.
    y_func
        .compute_root()
        .parallel(i);

    // Compute the per-row accumulators close to where they are consumed.
    // Since y_func(i) only needs acc(i), Halide can keep the tuple values
    // in registers and avoid allocating large temporary buffers.
    acc.compute_at(y_func, i);

    // Vectorize the inner part of the reduction over j to get dense vector
    // loads from A, B, and x. Halide will internally factor the reduction
    // as needed to make this safe (addition is associative/commutative).
    RVar j_outer("j_outer"), j_inner("j_inner");
    acc.update()
        .split(j, j_outer, j_inner, vec_width)
        .vectorize(j_inner);

    // Compile the kernel to machine code for the chosen target.
    y_func.compile_jit(target);

    // Measure execution time (kernel execution only; JIT time excluded).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
