    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // ---------------------------------------------------------------------
    // Halide algorithm.
    //
    // We compute:
    //
    //   tmp[i]    = sum_j A[i][j] * x[j]
    //   y_acc[i]  = sum_j B[i][j] * x[j]
    //   y[i]      = alpha * tmp[i] + beta * y_acc[i]
    //
    // To improve locality and reduce memory traffic, we fuse the two
    // dot-products into a single tuple-valued reduction:
    //
    //   acc(i) = { sum_j A[i][j] * x[j],
    //              sum_j B[i][j] * x[j] }
    //
    // and then form y[i] from acc(i)[0] and acc(i)[1].
    //
    // A and B are stored as (j, i) so the inner reduction over j
    // walks A(j, i) and B(j, i) contiguously in memory, while x(j)
    // is also accessed contiguously.
    // ---------------------------------------------------------------------
    Var i("i");
    RDom j(0, n, "j");  // reduction over columns j

    Func acc("acc");      // tuple-valued: {tmp, y_acc}
    Func y_func("y_func");

    // Pure definition: initialize both accumulators to zero.
    acc(i) = Tuple(cast<num_t>(0), cast<num_t>(0));

    // Reduction update: accumulate both dot products in one pass over j.
    acc(i) = Tuple(
        acc(i)[0] + A_param(j, i) * x_param(j),  // tmp
        acc(i)[1] + B_param(j, i) * x_param(j)   // y_acc
    );

    // Final combination stage: y[i] = alpha * tmp[i] + beta * y_acc[i]
    y_func(i) = Expr(alpha) * acc(i)[0] + Expr(beta) * acc(i)[1];

    // ---------------------------------------------------------------------
    // Scheduling.
    //
    // Goals:
    //   - Parallelize over rows i (outer dimension) to use many cores.
    //   - Vectorize the inner reduction over j to exploit SIMD.
    //   - Keep memory access patterns unit-stride on the inner loop:
    //       * A_param(j, i), B_param(j, i), x_param(j) all stride-1 in j.
    //
    // We compute the whole acc() at root, then y_func() from it.
    // ---------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    Var io("io"), ii("ii");

    // Compute the reduction result once, in parallel tiles of i.
    acc
        .compute_root()
        .split(i, io, ii, 64)   // tile rows by 64; adjust to taste / cache
        .parallel(io);          // parallel over row-tiles

    // For the reduction update:
    //   for io:
    //     for ii:
    //       for j:   (vectorized)
    acc.update()
        // Ensure j is innermost for good vectorization and unit-stride loads.
        .reorder(j, ii, io);

    if (vec_width > 1) {
        acc.update().vectorize(j, vec_width);
    }

    // Final y[i] computation: simple pointwise combination.
    // Parallelize over i and vectorize it as well.
    y_func
        .compute_root()
        .parallel(i);

    if (vec_width > 1) {
        y_func.vectorize(i, vec_width);
    }

    // Compile the kernel to machine code.
    y_func.compile_jit(target);

    // Measure execution time.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination and allow checking).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print timing in seconds on stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
