#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "gesummv.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A, B, x and scalars alpha, beta exactly as in the
 * original PolyBench C version.
 *
 * C layout:
 *   A[i][j], B[i][j] with i as row, j as column.
 *
 * Halide layout:
 *   Buffer<num_t,2> A(j, i)
 *   Buffer<num_t,2> B(j, i)
 *   Buffer<num_t,1> x(i)
 *
 * i is the slow (row) dimension, j is the fast (column) dimension.
 */
static
void init_array(int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B,
                Halide::Buffer<num_t, 1> x) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    Func init_A("init_A"), init_B("init_B"), init_x("init_x");

    // x[i] = (i % n) / n;
    init_x(i) = cast<num_t>(i % n) / cast<int>(n);

    // A[i][j] = ((i * j + 1) % n) / n;
    // Stored as A(j, i) in the Buffer.
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // B[i][j] = ((i * j + 2) % n) / n;
    // Stored as B(j, i) in the Buffer.
    init_B(j, i) = cast<num_t>((i * j + 2) % n) / cast<int>(n);

    // ------------------------------------------------------------------
    // Schedule for initialization
    //
    // We parallelize over rows (i) and vectorize over the fast
    // column dimension (j) or inner i sub-tiles to get good CPU
    // utilization even for large N.
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());
    const int tile_i = 64;  // row tile size – can be tuned

    // x is 1D: split i into tiles, parallelize outer, vectorize inner.
    {
        Var io("io"), ii("ii");
        init_x
            .compute_root()
            .split(i, io, ii, tile_i)
            .vectorize(ii, vec)
            .parallel(io);
    }

    // A and B are 2D: parallelize over rows (i), vectorize over columns (j).
    {
        Var i_outer("i_outer"), i_inner("i_inner");
        init_A
            .compute_root()
            .split(i, i_outer, i_inner, tile_i)
            .parallel(i_outer)
            .vectorize(j, vec);

        init_B
            .compute_root()
            .split(i, i_outer, i_inner, tile_i)
            .parallel(i_outer)
            .vectorize(j, vec);
    }

    // Realize the initialization Funcs into the provided Buffers.
    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    //  - A, B are N x N matrices, stored as (j, i) = (column, row)
    //  - x, y are N-length vectors.
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // ImageParams for A, B, x to feed into the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data.
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // ------------------------------------------------------------------
    // Halide GESUMMV pipeline
    //
    // Mathematical operation:
    //   tmp[i]   = sum_j A[i][j] * x[j]
    //   y_acc[i] = sum_j B[i][j] * x[j]
    //   y[i]     = alpha * tmp[i] + beta * y_acc[i]
    //
    // To reduce memory traffic, we compute the two inner sums together
    // using a Tuple-valued Func `sums`, so that for each (i, j) we load
    // A[i][j], B[i][j], and x[j] only once.
    // ------------------------------------------------------------------

    // Vars and reduction domain: i = row, j = column (fast dimension).
    Var i("i");
    RDom j(0, n, "j");  // j runs over columns [0, n)

    // sums(i)[0] = sum_j A[i][j] * x[j]
    // sums(i)[1] = sum_j B[i][j] * x[j]
    Func sums("sums");
    sums(i) = Tuple(cast<num_t>(0), cast<num_t>(0));
    sums(i) = Tuple(
        sums(i)[0] + A_param(j, i) * x_param(j),
        sums(i)[1] + B_param(j, i) * x_param(j)
    );

    // Final combination: y[i] = alpha * sums0[i] + beta * sums1[i]
    Func y_func("y_func");
    y_func(i) = Expr(alpha) * sums(i)[0] + Expr(beta) * sums(i)[1];

    // ------------------------------------------------------------------
    // Schedule for the GESUMMV pipeline
    //
    // - Parallelize across rows `i` (outer dimension).
    // - Vectorize across an inner sub-tile of `i` for better SIMD use.
    // - Keep the reduction over `j` (columns) as the innermost loop so
    //   that A(j, i) and B(j, i) are traversed contiguously in memory.
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());
    const int tile_i = 64;  // row tile size – tune for your machine

    // Fully materialize `sums` once, then read it from y_func.
    sums.compute_root();

    {
        // Schedule the reduction update of `sums`.
        Var i_outer("i_outer"), i_inner("i_inner");
        sums.update()
            .split(i, i_outer, i_inner, tile_i)
            .parallel(i_outer)      // parallel over row tiles
            .vectorize(i_inner, vec);  // SIMD across rows within a tile
    }

    {
        // Schedule the final combination y_func(i).
        Var i_outer("i_outer_y"), i_inner("i_inner_y");
        y_func
            .compute_root()
            .split(i, i_outer, i_inner, tile_i)
            .parallel(i_outer)
            .vectorize(i_inner, vec);
    }

    // Compile the kernel to machine code for the host target.
    y_func.compile_jit(target);

    // Measure execution time.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination and allow checking).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print timing in seconds on stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
